import { PASSWORD, USERS, expect, test } from "../../fixtures";

test("successful sign-in returns a session", { tag: "@AUTH-01" }, async ({ request }) => {
  // Act
  const response = await request.post("/api/auth/login", {
    data: { email: USERS.member, password: PASSWORD },
  });

  // Assert
  expect(response.status(), await response.text()).toBe(200);
  const body = await response.json();
  expect(typeof body.access_token, await response.text()).toBe("string");
  expect(body.access_token.length, await response.text()).toBeGreaterThan(0);

  const cookie = response.headersArray().find((h) => h.name.toLowerCase() === "set-cookie" && h.value.startsWith("session="));
  expect(cookie, "a session cookie is set").toBeDefined();
  expect(cookie?.value.toLowerCase(), cookie?.value).toContain("httponly");
});
